from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="150" viewBox="0 0 680 150" role="img">\n<title>Git log graph</title><desc>commit graph lines</desc>\n<style>@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}} .line{stroke-dasharray:300;stroke-dashoffset:300;animation:draw 1s forwards} @keyframes draw{to{stroke-dashoffset:0}}</style>\n<rect width="680" height="150" rx="16" fill="#0f172a"/>\n<text x="20" y="28" fill="#e2e8f0" font-family="monospace" font-size="12">GIT LOG --graph --oneline</text>\n<g transform="translate(20,40)">\n  <circle r="4" cx="10" cy="10" fill="#22c55e"/><text x="24" y="14" fill="#e2e8f0" font-family="monospace" font-size="10">665320a Merge PR #24</text>\n  <circle r="4" cx="10" cy="30" fill="#38bdf8"/><text x="24" y="34" fill="#e2e8f0" font-family="monospace" font-size="10">79a218a Витрина x4 (neon/stadium)</text>\n  <circle r="4" cx="10" cy="50" fill="#a78bfa"/><text x="24" y="54" fill="#e2e8f0" font-family="monospace" font-size="10">4a860f5 Merge PR #23</text>\n  <path d="M10 14 L10 26 M10 34 L10 46" stroke="#334155" stroke-width="2" class="line"/>\n  <text x="300" y="90" fill="#64748b" font-family="monospace" font-size="9">reproduced from git log --graph · atlas/samples/commits.mmd → PNG</text>\n</g>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','git-log-graph.svg').write_text(svg, encoding='utf-8')
print('Wrote assets/git-log-graph.svg')
